namespace moon {
struct GradientMapSettings {std::vector<GradientStop> stops{{0,0xff000000},{1,0xffffffff}};bool steps=false,reverse=false;int dither=0;};
inline GradientMapSettings normalizeGradientMap(GradientMapSettings value){std::vector<GradientStop> stops;std::size_t inputCount=0;for(auto stop:value.stops){if(inputCount++>=256)break;if(!std::isfinite(stop.position))continue;stop.position=std::clamp(stop.position,0.0,1.0);stop.color|=0xff000000;stops.push_back(stop);}std::stable_sort(stops.begin(),stops.end(),[](auto a,auto b){return a.position<b.position;});if(stops.size()<2)stops={{0,0xff000000},{1,0xffffffff}};value.stops=std::move(stops);if(value.dither<0||value.dither>8)value.dither=0;return value;}
inline std::string gradientMapSignature(const GradientMapSettings& settings){auto s=normalizeGradientMap(settings);std::ostringstream key;key<<s.steps<<':'<<s.reverse<<':'<<s.dither<<std::setprecision(17);for(auto stop:s.stops)key<<':'<<stop.position<<':'<<stop.color;return key.str();}
class GradientMapSampler {int period_;std::shared_ptr<std::vector<std::uint32_t>> table_;public:
 explicit GradientMapSampler(GradientMapSettings value){auto s=normalizeGradientMap(value);period_=s.dither?gradientDitherPeriod(s.dither):1;static std::mutex mutex;static std::vector<std::pair<std::string,std::shared_ptr<std::vector<std::uint32_t>>>> cache;const auto key=gradientMapSignature(s);{std::lock_guard<std::mutex> lock(mutex);for(auto& entry:cache)if(entry.first==key){table_=entry.second;return;}}table_=std::make_shared<std::vector<std::uint32_t>>(period_*period_*256);for(int luminance=0;luminance<256;++luminance){double amount=s.reverse?1-luminance/255.0:luminance/255.0;auto found=std::find_if(s.stops.begin(),s.stops.end(),[&](auto stop){return stop.position>=amount;});std::size_t right=found==s.stops.end()?s.stops.size()-1:std::size_t(found-s.stops.begin()),left=right?right-1:0;const auto a=s.stops[left],b=s.stops[right];double fraction=b.position>a.position?std::clamp((amount-a.position)/(b.position-a.position),0.0,1.0):0;for(int y=0;y<period_;++y)for(int x=0;x<period_;++x){auto color=s.dither?fraction>=(gradientDitherStage(s.dither,x,y)+.5)/gradientDitherCount(s.dither)?b.color:a.color:s.steps?(fraction<.5?a.color:b.color):gradientInterpolate(a.color,b.color,fraction);(*table_)[(y*period_+x)*256+luminance]=color&0xffffff;}}{std::lock_guard<std::mutex> lock(mutex);if(cache.size()>=16)cache.erase(cache.begin());cache.emplace_back(key,table_);}}
 std::uint32_t operator()(std::uint32_t color,int x=0,int y=0)const{if(!(color>>24))return color;int luminance=gradientRound((color&255)*.2126+((color>>8)&255)*.7152+((color>>16)&255)*.0722);auto mod=[&](int v){return (v%period_+period_)%period_;};return (color&0xff000000)|(*table_)[(mod(y)*period_+mod(x))*256+luminance];}
};
struct GradientMapPreset {std::u32string name;GradientMapSettings settings;};
inline const std::vector<GradientMapPreset>& gradientMapBuiltins(){static const auto presets=[](){std::vector<GradientMapPreset> out;auto ramp=[&](std::u32string name,std::initializer_list<std::uint32_t> colors,bool steps=false){GradientMapSettings s;s.stops.clear();int i=0;for(auto color:colors){auto c=0xff000000|((color>>16)&255)|(color&0xff00)|((color&255)<<16);s.stops.push_back({double(i++)/(colors.size()-1),c});}s.steps=steps;out.push_back({name,s});};ramp(U"灰度",{0x000000,0xffffff});ramp(U"银色",{0x141b26,0x6b7b8e,0xf0f5ff,0x8795a8,0xffffff});ramp(U"金色",{0x301a07,0x946119,0xf6cf62,0xa56c1c,0xfff7c0});ramp(U"铜色",{0x291410,0x88432b,0xe69363,0xa35435,0xffe1b1});ramp(U"海洋",{0x081b39,0x155879,0x30afbc,0xd2f4e7});ramp(U"日落",{0x25133d,0x813d75,0xec7862,0xffe6a2});ramp(U"Game Boy",{0x0f380f,0x306230,0x8bac0f,0x9bbc0f},true);ramp(U"棕褐",{0x28160e,0xffecc0});return out;}();return presets;}
}
